<?php require_once '../includes.php'; if(!empty($_SESSION['admin_logged_in'])) redirect('index.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $s=settings(); if(post('username')===$s['admin_user'] && post('password')===$s['admin_password']){$_SESSION['admin_logged_in']=true;redirect('index.php');} $error='Invalid username or password.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Doctor Login</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="login-wrap"><div class="login-card"><img src="../assets/images/logo.png" alt="logo"><h2 style="text-align:center;color:var(--dark)">Doctor / Admin Panel</h2><?php if($error): ?><div class="notice danger"><?=e($error)?></div><?php endif; ?><form method="post"><div class="field"><label>Username</label><input name="username" required></div><br><div class="field"><label>Password</label><input type="password" name="password" required></div><br><button class="btn" style="width:100%">Login</button></form><p style="text-align:center;font-size:12px;color:#777;margin-bottom:0">Change credentials in db.php before production.</p></div></div></body></html>
